import{_ as t,c as a,o as e,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"周易通論卷一","description":"周易通論 - 周易通論卷一","frontmatter":{"title":"周易通論卷一","description":"周易通論 - 周易通論卷一"},"headers":[],"relativePath":"classics/tonglun/002.md","filePath":"classics/tonglun/002.md"}'),n={name:"classics/tonglun/002.md"};function r(o,p,c,_,i,l){return e(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="周易通論卷一" tabindex="-1">周易通論卷一 <a class="header-anchor" href="#周易通論卷一" aria-label="Permalink to “周易通論卷一”">​</a></h1><p>欽定四庫全書</p><p>大學士李光地撰</p><p>易之興也最古，其源流不可悉知。「三易」之名，及畫卦、重卦、名卦之人，諸儒之論亦復不一。約之，則「三易」之說可通者有二：一曰夏連山、殷歸藏、週週易也；一曰連山炎帝、歸藏黃帝、周易文王也。畫卦、重卦、名卦之人，則有三說：一曰伏羲畫八卦，因自重之而自名之也；一曰伏羲畫八卦，至文王乃重而名之也；一曰伏羲畫八卦而重之，文王始名之也。今按，以「三易」為夏、殷、周者，據記有「夏時坤乾」之文也。謂為炎帝、黃帝、文王者，連山炎帝之號；歸藏黃帝之號，而周文王之國號也。鄭康成斷從後說，今始沿之可也。周禮雲：「三易之經卦皆八，其別皆六十有四」，則非文王始重卦可知。然伏羲雖已重卦，名則未備，蓋其時僅有八卦之名而已。故繫辭傳曰：「其稱名也，雜而不越，於稽其類，其衰世之意耶？」言卦之稱名，錯雜事物，周於人用，以其類考之，非中古以後更歷世變者不能及也。況「履虎尾」、「否之匪人」、「同人於野」、「艮其背」、「中孚豚魚」之類，皆辭與名連為義，則是一手所繫，非仍舊名而增加之也。朱子於乾卦下本義雲：三奇之卦，名之曰乾。是以八卦之名為伏羲所命。至屯卦下則無說，而於系傳稱名，則以為卦名也。是以六十四卦之名為文王所命也。於理近是，今亦從之。彖辭、爻辭，何人所繫？夫子未嘗分別。先儒直以箕子明夷、王享岐山之類，事出文王之後，斷爻辭為周公所作。然考夫子贊易，如所謂「易之序也，爻之辭也，是故謂之象」，「是故謂之爻」，每以爻與象對，而反不及彖，似爻之起亦非在彖後者。意者系爻固文王之意，而周公成之與？惟曰：「彖者言乎象者也，爻者，言乎變者也。彖者材也，爻者效天下之動者也。智者觀其彖辭，則思過半矣。」分別卦爻辭先後，其理甚明，先儒之說可循用也。夫子贊易曰：十翼者，彖上傳、彖下傳、象上傳、象下傳、乾坤文言、繫辭上傳、繫辭下傳、說卦、序卦、雜卦也。所謂象傳者，兼二體，大象及六爻之小象也。按漢書本為經二卷，傳十卷，經傳離異，不相附屬。自費直始以彖、象傳綴於每卦經後，如乾、坤之例。王弼又自坤卦以下，以彖傳、大象傳附彖，小象傳附爻，則今現行之易是也。朱子及東萊呂氏復古經傳之舊，本義之作，實據漢書，故凡「彖曰」、「象曰」、「文言曰」之類為王弼所加者，悉已刪去，而別有卷首標題，即彖傳、「象傳」、文言傳等目。其彖傳題下則注云：「彖即文王所繫之辭；傳者，夫子釋經之辭也。」象傳題下則注云：「象者，卦之上下兩象及兩象之六爻，周公所繫之辭也。」十二卷古易於是乎各得其所矣。明初律令兼用程朱傳義，及永樂中修大全書，離析本義，以從程傳之序，故後雖本義孤行，而其序遂不復。學者讀乾卦彖象傳標題下注，茫然不省所指，故有以大象為周公作者，誤由茲起也。為宜別刻本義原本，以悟初學。本義卷首諸圖，朱子所作也。秦漢以來，伏羲畫卦根本次第無言及者。邵康節先天之學源出希夷，程子不信，而朱子始表章之，此諸圖所由作也。然惟八卦方位圓圖及六十四卦圓圖、方圖為邵氏之舊，其首之以橫圖，則朱子用邵子之意而摹畫以示人者，見於答袁機仲諸書可見也。間嘗論易之源流，四聖之後，四賢之功為不可掩。蓋自周子標太極之指，邵子定兩儀以下之次，而伏羲之意明，程子歸之於性命道德之要，其學以尚辭為先，而文周之理得，朱子收而兼用之，又特揭卜筮以存易之本教，分別象佔以盡易之變通，於是乎由孔聖以追羲、文，而易之道粲然備矣。自漢以還，非無傳者，然揚雄以玄為宗，則純乎老氏矣。其與周子太極，可若是班乎？其法以三三起，雖與易卦相近，而非自然之理。八十一首之序，猶仍卦氣之謬也。其與邵氏先天之法，亦未可同日語。王弼生於魏、晉，祖尚玄虛，即復之一卦，而宗指與程傳迥別。蓋王氏所謂復者，虛靜之室；程傳所謂復者，仁義之心。其餘義準是矣。然當朱子時，太極抑於陸子兄弟，先天毀於袁樞、林栗，程學訾者亦眾。苟非朱子一一極辯，則三家之學且熄，而卜筮象佔之說，又所以佐三家之未逮也。自時厥後，好議論者猶將反之，故黃震攻康節之圖，王禕申河洛之辯，羅欽順滅太極之書，至於以卜筮為朱子詬厲者，又紛然而未已。夫學欲博而不欲雜，眾言淆亂則折諸聖。易之為書，立說者最多，其雜且亂甚矣。夫苟不折以列聖群賢，而惟博之好，則易之賊也。航於斷港絕潢，而望至於海，不亦難乎？</p><p>三代學校之教，詩、書、禮、樂四術而已。易掌於太卜，國史掌於史官，乃專官之學，未嘗施於學校也。故韓宣子至魯，乃見易象、春秋，則知詩、書、禮、樂列國有傳，而二書者獨𮤲。自夫子贊修之後，稍見於世矣。故記禮者名為六經，而莊周之徒頗知其意者，亦往往並述焉。然自秦政燔經，獨存卜筮、醫藥、種樹之書，而易幸不毀，則知其時猶未直目之經，學士先生猶未流行誦習，以故卜筮家專司而世守之，是則易之本教然也。漢人雖稱六藝，然田何、施、孟、梁丘之學皆不傳，不知其說云何。焦贛、京房衍為生克休咎之佔，其敝以星日氣候推配，雖曰流蕩，然可知卜筮之教，展轉相沿，久則難變也。揚雄作玄疑易，雖襲京、焦之緒，而頗推道德性命之指。至王弼始純以理言易，而後之談經者宗焉。是書著述莫盛於宋，惟邵康節之學有傳，而猶以象數見譏。其餘儒者所得，有淺有深，然大要承輔嗣之意，皆以易為言理之書而已。夫孔子嘗言易矣，曰：「和順於道德而理於義，窮理盡性以至於命。」則謂易言理是也。然本畫卦繫辭之初，則主於卜筮以明民，非如他書直闡其理，直述其事者也。朱子深探其本，作本義一編，專歸卜筮，然而至今以為訾謷，蓋恐狹易之用，小易之道，而使經為伎術者流也。殊不知易之用，以卜筮而益周，易之道，以卜筮而益妙。而凡經之象數辭義，皆以卜筮觀之而後可通，初非小技末術之比也。今曰作易者，言理以教人爾，則施於學士，而阻於愚氓，其用不周矣。偏言一理，而不足以該於無窮，其道不妙矣。卦象之泛取，蓍數之旁通，其於理也，雜而不切矣。大有元亨，初六無咎，其於理也，略而難明矣。避其為小技末術，而反入於枝離晦昧之歸，乃不虞其重為易病也乎？是故朱子之大有功於易卜筮之說也，有得於此，然後可以言潔靜精微之要，而凡散殊清通，無所推而不達，道德性命亦無所求而不得矣。</p><p>朱子既復經、傳次序，今不遵之，而從王弼舊本，何也？曰：「朱子之復古經、傳也，慮四聖之書之混而為一也；今之仍舊本也，慮四聖之意之離而為二也。」蓋後世之注經也，文義訓詁而已，而又未必其得，故善讀經者，且涵泳乎經文，使之浹洽，然後參以註解，未失也。若四聖之書，先後如一人之所為，互發相備，必合之而後識化工之神，則未可以離異觀也。故以文、周彖、爻言之，彖於坤言牝馬，可謂盡坤之情矣。乾未有象也，六爻則於乾言龍，以盡乾之道。坤彖言君子牝馬之貞，有東北、西南，以應地之方也。乾爻則言聖人之龍德，有潛見飛躍，以應天之時。此則彖爻之自相補備者也。以夫子之傳言之，乾彖曰「元亨利貞」，未有四時之義也，彖傳釋之，而曰「資始流形」，曰「各正保合」，則知四德之即四時矣。坤彖曰西南東北，未有四德之義也，文言釋之，於西南曰「含物化光」，於東北曰「順天時行」，則知四方之即四德矣。乾爻之總辭曰「見群龍無首」，著乾之居首而不為首也。象傳則於坤曰「以大終」，著坤之居終而不為終焉。坤爻之總辭曰「用六永貞」，明用六之義，所重在貞也。象傳則於乾曰「乾元用九」，明用九之義，所重在元也。此又經傳之相為補備者，所謂先後如一人之所為也。若乃屯蒙以下諸卦，則皆有不可相離者。蓋如彖言「建侯」，爻亦曰「建侯」，則知「侯」之為初矣；彖言「童蒙」，爻亦言「童蒙」，則知「童」之為五矣。此彖爻之互相發明者也。然如訟之彖曰「利見大人」，爻曰「訟元吉」，其意方明也，彖傳曰「尚中正」，則知「大人」之為五矣。師之彖曰「丈人吉」，爻曰「在師中」，其意未明也，彖傳曰「剛中而應」，則知「丈人」之為二矣。又如晉之「康侯」，而九四不足以當之，則未知其所指也，彖傳曰「柔進而上行」，則知卦之「康侯」，不在四而在五矣。困之「大人」，亦未知其所指也，彖傳曰「以剛中也」，則知卦之「大人」，不在陰而在陽矣。蓋上以釋文王名辭之意，而下以得周公繫辭之心，故彖傳為卦爻之樞要。至於大象，則卦之命名所取為多，故夫子特表而出之。凡</p><p>彖傳釋名，有兼取數義者，有直釋名辭者。其兼取數義者，命名之意廣有所取也；其直釋名辭者，命名之意專在大象也。易者象也，象也者像也，此大象所以尤為一卦之要也。小象之傳，辭則簡矣，而義至精。或推言爻之德位，而本之於時；或旁及爻之與應，而參之以比；或廣其言外之意，而言中之指愈明；或略其言中之詞，而所言之理愈備。後之賢者，重言累釋而不能盡，聖人輒以單辭括之。此皆經、傳之相為發明者，學者當作一意求之，則其文宜相附近，此今日仍王氏舊本之意也。</p><p>伏羲之畫，無文而無所不包，文王命之以名，則既偏於一矣。然其審於象也精，而天道民故備焉。此所以為雜而不越，因憂患而有作者也。其辭也，所以發名之意也。如是以開物成務，其亦足矣。其又析為六爻之辭，何也？曰：卦者，原始終以為質，錯上下以取象者也。然既有始終矣，則孰為始，孰為終？不可不極其變也。既有上下矣，則孰為上？孰為下？不可不辨其物也。有始終上下，則有消息當否矣，而孰為息？孰為消？孰為當？孰為否？不可不研其幾而撰其德也。以泰、否兩卦論之，其名卦繫辭取於交不交及往來之義矣。然有交不交，則上下判焉；有往有來，則始終分焉。原其始，則自「否」而泰，自「泰」而「否」者也。拔茅而來所以吉，拔茅而去所以亨也。要其終，則「泰」而復否，「否」而復「泰」者也。「城復於隍」，所以吝；「休否傾否」，所以吉也。交而泰，其「泰」在上，故六五有「歸妹」之德，而後九二得盡中行之義矣。不交而否，其「否」在下，故六二守「否亨」之節，而九五當存其亡之心矣。「卦包乎爻而舉其綱，爻析乎卦而窮其分。爻不立，無以發卦之縕，而冒天下之道。是故卦爻者，相為表裡，相為經緯者也。」此文、周之書所為二而一者也。</p><p>名義有相似而累見者，如屯、蹇、困相似也，比、同人、隨相似也，頤、井、鼎相似也，晉、升、漸相似也。若此之類，其卦名相似，其彖意爻義亦每重見疊出者，何也？曰：此聖人憂患之心所以為至也。蓋理有切於民生日用者，一則煩辭屢申，欲其不忘也；一則辨時析義，欲其不差也。人生於憂患，則屯、蹇、困之義最切矣。非斯人之徒與而誰與？則「比」、同人、隨之義最切矣。物不可不養，而養必以正，則「頤」、井、「鼎」之義最切矣。人莫不好進，而進必以正，則「晉」、升、「漸」之義最切矣。廣設其名，丁寧其意，凡使之知懼而勿忘焉已矣。而且屯宜動也，「蹇」、困宜止也，相似而不同也。「比」者以分相屬也，「同人」者，以情相親也，「隨」者以德相下也，相似而不同也。「頤」者，自養而兼養人之義也，「井」所以養民也，「鼎」所以養賢也，相似而不同也。「晉」者，既進而盛也，「升」者，方進而通也；「漸」者，自方進至既進，緩而有序也，相似而不同也。時義之精也，在毫釐之間，不辨析焉，則用之或差，是故不可以不詳也。至於復、臨、泰、壯、夬，同為陽長之卦，姤、遁、否、剝，同為陰長之卦，然其微著先後之間，氣候不同，而義理亦變。惟聖人為能辨別其當時之幾，而審度乎處之之分，莫不於其名卦繫辭而見之矣。</p><p>六十四卦皆時也，惟八純卦不可以時言。非無時也，根於天地之理，人心之德。其為時也，述天理而時措，不可以在外之所遇者言也。乾者，健德也。坤者，順德也。震者，動德也。艮者，止德也。巽者，入德也。兌者，說德也；離者，明德也。惟坎曰「陷」曰「險」，不可以心德言，故於重卦之名，加一「習」字，與七卦之例別。蓋人心惟危，故其心德必有所陷，陷則險矣，於是乎不可聽其心之陷溺，而必更習於險以出乎險。孟子所謂「困心衡慮，動心忍性」，皆其事也。如是則亦為人心之德，與七卦等矣。此八卦者，與時偕行，豈非時乎？然主於所施，不主於所遇。是故震與履皆論戒懼之道而不同，震者，心之德也；履者，時之宜也。離與豐皆論昏明之效而不同：離者，心之德也；豐者，時之宜也。艮與鹹皆論動靜之學而不同：艮者，心之德也；鹹者，時之宜也。坎與屯、需、蹇、困皆論處險之義而亦不同，習坎者，心之德也；屯、需、蹇、困，時之宜也。處時之道，不外乎人心之德，此八卦所以經緯乎六十四卦之中，而義所以獨為大也。釋經者曰：「健莫如天，順莫如地，動莫如雷，入莫如風，明莫如火，止莫如山，說莫如澤。」是皆然矣。曰險莫如水，則有未盡當曰行險莫如水，斯為水之德爾。由此言之，卦名不加以「習」字，得乎？</p><p>聖人系彖之時，雖通觀其卦象、卦德以定名辭之義，然於爻位尤致詳焉。蓋有因爻位以名卦者，師、比、小畜、履、同人、大有、謙、豫、剝、復、夬、姤之類是也。有名雖別取，而爻位之義發於辭者，屯蒙之「建侯求我」指初二，訟、蹇、萃、巽之「大人」指九五之類是也。是二者，皆謂論卦之主爻，但就文王之名辭觀之，有包涵其意而未明者矣。至六爻之系，則辭有吉凶，義有輕重，而名辭之意，因以可見。如師則正九二之為長子，而卦之所以為師者，此矣。比則正九五之為王，而卦之所以為比者，此矣。謙之九三曰「勞謙」，而卦之所以為謙者，此矣。豫之九四曰「由豫」，而卦之所以為「豫」者，此矣。剝之上九曰「碩果」，而卦之所以為剝者，此矣。復之初九曰「不遠復」，而卦之所以為「復」者，此矣。又如屯之初曰「利建侯」，而辭所謂「建侯」者，此矣。蒙之五曰「童蒙」，而辭所謂「求我」者，此矣。訟之五曰「訟元吉」，蹇之五曰「大蹇朋來」，萃之五曰「萃有位」，巽之五曰「貞吉悔亡，無不利」，而辭所謂「大人」者，此矣。蓋爻之意，雖根於卦而後可明，而卦之意，亦參於爻而後可知。卦爻相求，則所謂主爻者得矣。主爻者得，則其餘爻之或吉或兇，因是可推。何則？凡卦義善者，爻能合德則吉，反之則兇也。卦義不善者，爻能反之則吉，合德則兇也。故師、比、謙、豫之類，主爻之吉者也，以其德與時適也。若其當與時反者，則為主者反不得吉。如訟之上九，則終訟者也；履之六三，則咥人者也；明夷上六，則明所以夷也；歸妹上六，則妹所以歸也。主爻吉，則餘爻之吉者，必其德與主爻類者也。非然，則其比應也。而反是者，則兇。主爻兇，則餘爻之兇者，必其德與主爻類者也。非然，則其比應也。而反是者，則吉。又主爻不拘於一，如蒙之九二，固主爻矣，六五以「童蒙」應之，則亦主爻也。師之九二，固主爻矣，六五使長子帥師，則亦主爻也。履之六三，固主爻矣，九四有「虎尾」之象，則亦主爻也。泰之九二，固主爻矣，六五為下交之主，則亦主爻也。又如臨之初、二，觀之五、上，坎、離之二、五，萃、升之四、五，則皆自卦義而定，不妨兩為卦主也。又如震有兩主，而其重在初。艮有兩主，而其重在上。既濟二、五得中，而其重在二。未濟二、五得中，而其重在五。此則因卦義而變者。履之三、四象「虎尾」，而其吉在四。頤之初、上象「頤」，而其兇在初。大過三、四象「棟」，而其吉在四。小過初、上象「鳥」，而其尤兇在初。此則又因物象而變者。若此之類，推說難盡，姑舉其槩，各隨卦義爻才而觀之可也。凡卦有無主者，則以其義甚大，而爻德不足以配。如「同人於野」之義至大，六二之吝，固不足以當之矣。惟上九居卦外，有「野」之象，而其德非中正，故僅止於「郊」而已。恆久之義至大，六五之「貞」，固不足以當之矣。惟九二剛中，有久中之德，然位失其正，故止於悔亡而已。是二卦者，無主爻也。蓋撰德於卦，則指爻以為主者，卦象之正也。繫辭其爻，因卦義之大，而必審論其才德者，爻義之精也。艮以人身取象，則當以六四背位為主。然止者剛德，而四柔也，故以上之止體為主，四止於無咎，而上吉也。中孚以中虛取象，則當以三四為主。然孚者實德、中德，三四陰而不中，故以二五之剛中為主，六四雖有幾望之吉，而亦不得為主也。然乾坤之義，大之至矣，而其所以有主者，則以乾五剛健中正，備天之德也；坤二柔順中正，備地之德也。故彖傳所謂「乘龍御天」，「首出咸寧」者，皆以九五之德位當之也。文言所謂動剛德方者，皆以六二之德當之也。自乾坤發此例，而六十四卦因之，其彖傳有贊爻德以贊卦者，皆此例也。</p><p>所謂佔辭者，元亨利貞也，吉凶悔吝無咎也，其目之大者也。考之於經，則爻無元亨，止於「元吉」、「大吉」而已，或止曰亨而已。卦無吝而悔，亦僅見於革彖而已。聖人於此，亦有意否乎？曰：元亨利貞者，天道之常，而貫乎人事者也。吉凶悔吝者，人事之致，而通乎天道者也。卦本乎天道，而元亨者，天道之大者也，故爻不得而用之也。爻主乎人事，而悔吝者，人事之細者也，故卦不得而及之也。且「元亨」之為大也，不獨爻無用焉，而見於卦者亦少。自乾坤之外，惟屯、隨、臨、無妄、革五卦，備「元亨利貞」之辭。蓋屯與革，則天時之大者；隨人與臨人，則人事之大者。無妄，則天人之德之至者也。此外而曰「元亨」者，亦惟大有、蠱、升、鼎而已。蠱壞之極而更新之，其義與屯、革相亞，此所以曰「元亨」也。大有、升、鼎三卦，則皆以賢人取義。蓋大有者，所有者大，賢人之眾多也。鼎以養賢，賢人之得養也。升以進賢，賢人之得用也。易之義，莫美於用賢者，故大有與鼎，皆直曰「元亨」，而無餘辭。升雖有餘辭，皆以足「元亨」之義，而無他戒，為諸卦不能及者，意豈不深哉！彖辭言「元亨」，無言「大亨」者，而夫子以「大亨」釋之，則「大」與「元」本一義也。然爻辭或言「元吉」，或言「大吉」，則亦不能無少差別。考之坤五、訟五、履上、泰五、復初、大畜四、離二、損五、益初、益五、井上、渙四，皆言「元吉」。惟家人四、萃四、升初、鼎上，言「大吉」。蓋坤五以中順之德配乾，離二亦以中順而合坤德，故坤曰「牝馬」，配乾之義也；離曰「牝牛」，肖坤之義也。其辭皆曰「黃」，以此也。德至中和而極，故佔皆「元吉」。履上則德之成也，復初則德之本也，其佔亦「元吉」。此四爻皆以其德之純言也。餘則凡言「元吉」者，多指吉之在天下者也。凡言「大吉」者，多指吉之在一人者也。故均之益也，家人四富其家者也；益五富天下者也。均之聚也，萃四聚其下而猶恐有樹私之嫌，渙四「渙其群」則已極乎大公之善也。均之進也，益初之義，在忘身以酬上；升初之義，在見允而得升也。均之養也，井之義為養民，則在上而養道成者，是民得養也。鼎之義為養賢，則至上而養道成者，是己得養也。至於訟五、畜四，則有無訟刑措之風焉；泰五、損五，則有虛中受下之美焉。是皆非一人之吉，而天下之吉，此所以不特曰「大」，而曰「元」也。彖傳有喜「有慶」之義亦然。彖爻辭有言「利」者，有言「用」者，有言「不利」者，有言「勿用」者，意相近而辭不同。蓋佔者與卦爻有相為賓主之例。言利不利者，以佔者當卦爻，謂如此之德，如此之時位，則其利不利如此也。言用不用者，謂卦爻之德之時如此，佔者可用以如此，不可用以如此也。細觀之，其義亦須有別。凡言「利」者，皆其事後之利。如訟非得大人不決；蹇非得大人不濟；需「不犯難」，同人能得眾心，有可以涉川之理。又需者，將以進也；同人者，將以濟也。故皆言「利」，事後之辭也。凡言「用」者，則即今而可用。如升則遇時之卦，見大人而無憂；謙謙則德之至，「涉大川」而必濟。故皆言「用」，當事之辭也。凡言「不利」者，事無可為之稱。如剝之「小人長」，則其時之「不利攸往」也；無妄之「匪正有眚」，則其德之「不利攸往」也。故言「不利」，蓋終無可往之理也。凡言「勿用」者，暫且勿用之意。如屯雖動乎險，然猶未可輕有所往；遁雖其勢當去，然亦未可輕有所往。故言「勿用」，蓋恐其疑於可往，而戒以未可往也。然則「利」之詞緩於「用」，「不利」之詞又急於「勿用」。通事後而論之，則利者猶在後也，故緩；不利者，終無可為也，故急。即當事而論之，則用者即今可用也，故急。「勿用」者，惟此時勿用而已，故緩。若夫虛言「無不利」、「無攸利」者，亦包當事事後之辭也。虛言「勿用」者，亦是且就其時斷之之辭也。頤之三，既曰「勿用」，又曰「無攸利」，則其辭彌甚矣。「利用礿」，利用亨祀，祭祀。及王用亨於西山、岐山，「王用亨於帝」之義，亦然。爻辭無「元亨」，而曰「利貞」者亦少。蓋變「元亨」曰「元吉」、「大吉」，變「利貞」曰「貞吉」。所以然者，卦之義全爻則偏指一事而言，故變其文以別之也。其曰「利永貞」者，以永為貞也。「利居貞」者，以居為貞也。「利艱貞」者，以艱為貞也。「利於不息之貞」者，以不息為貞也。「利幽人、武人之貞」者，以幽人、武人為貞也。此又本於坤、明夷彖辭之例，然皆偏指一事而言者也。凡言「貞吉」於辭之後者，即其辭所言之義，而貞固守之則吉也，「需於酒食」、「鳴謙，介於石」之類是也。言「貞吉」於辭之前者，爻有貞吉之義，而辭又有他戒也，鹹四、壯四、升五、巽五、未濟四五是也。「悔亡」、「無咎」之義亦然。惟壯二直曰「貞吉」，恆二直曰「悔亡」，解初直曰「無咎」，前後更無他辭，則以爻義已足示人，觀象之例也。凡言「悔亡」者，有悔而可亡也。「無悔」者，無可悔也。然則「無悔」之義，進於「悔亡」，故鹹四言「悔亡」，至五則言「無悔」；大壯四言「悔亡」，至五則言「無悔」；渙二言「悔亡」，至三則言「無悔」；未濟四言「悔亡」，至五則言「無悔」。以其辭義先後考之，無悔進於悔亡可知矣。雖以復初之吉，然無祗於悔，與敦復無悔，亦須有先後也。凡易中言「悔亡」、「無悔」者，以此別之。</p><p>先儒說「貞兇」，有云「雖貞亦兇」者，有言「貞乎此則兇」者，有言「決定是兇」者，是有三例也。說「無咎」，既為補過之義，又云「自取兇害，無所歸咎」，是有兩例也。夫苟二三其例，則是適以眩夫佔者，而又何以斷天下之疑乎？故夫「貞」者，正也，固也。凡言「貞吉」者，兼正固之義，固由正生也。凡言「貞兇」、「貞吝」、「貞厲」者，主乎固之義，蓋自以為正而固守之也。其設戒亦不純蒙上句，蓋有與上句相反為義者，如泰道之終，「城復於隍」矣，斯時也，「勿用師，自邑告命」則可矣。如固守其常而力爭之，則「吝」也。晉道之極，「晉其角」矣，斯時也，惟自治其私，則雖危而吉，無咎矣。如固守其常，知進而不知退，則「吝」也。此皆不蒙上句而相反為義者，如「弟子輿尸，貞兇」，「晉如鼫鼠，貞厲，喪其資斧，貞兇」，則蒙上句直說，謂固常如此而不知反，則危且兇也。二者文意不同，然要為不可固守之佔，則無兩例明矣。傳言「無咎者，善補過也」，則「無咎」非兇辭可知。但以大過之上、節之三，遂謂有變例焉。然過上際時窮而有處之之義，節三失時義而有改悔之機，是皆可以補過之例求之，不必變也。蓋過涉滅頂，時窮而兇矣。然以柔為說主，不與時爭，則「無咎」之道也。不言其所以無咎者，解初六之例也。「不節若」，宜得「兇」矣。然因不節而遂「嗟若」，亦「無咎」之道也，臨六三之例也。況節三象傳與同人初爻同，則「無咎」之義亦應同。雖解三「又誰咎也」，為非善詞，然此兩爻有「無咎」之文，則象傳為直解「無咎」之義，言人安得而咎我也。解三爻無「無咎」之文，而曰「貞吝」，則象傳為解「貞吝」之義，言我安得而咎人也。其辭固不相病也。惟其例之一，是以辭之指有難明者，皆以其佔戒讀之而可知。故曰：「定之以吉凶，所以斷也。」</p><p>王仲淹曰：「趨時有六動焉，吉凶悔吝，所以不同。」其說善矣。然趨時之義，不可不辨也。近代說易，所謂時者，皆似有一時於此，而眾人趨之爾。故其象君臣者，皆若同朝；象上下者，皆若同事。其為時也，既局於一而不通；其趨時也，又以互相牽合而說義多不貫，此則講解之大患也。夫時也者，六位莫不有焉，各立其位，以指其時，非必如並生一世，並營一事者也。如言屯也，蹇也，莫不有屯焉，莫不有蹇焉，不必皆言濟時之艱難，平時之險阻也。「大有」也，「豫」也，莫不有所有焉，莫不有所「豫」焉，不必皆言際明盛之朝，值和樂之世也。如此，則何至局於一而不通乎？且莫不有「屯」矣，則初有初之「屯」，五有五之「屯」，非五因初而「屯膏」也。莫不有「豫」矣，則四有四之「豫」，五有五之「豫」，非五因四而「貞疾」也。如此，則何至互相牽合而說不貫乎？蓋必其所謂「時」者，廣設而周於事，所謂「動而趨時」者，隨所處而盡其理，然後有以得聖人貞一群動之心，而於辭也幾矣。是故一世之治亂窮通，時也；一身之行止動靜，亦時也。因其人，因其事，各有時焉，而各趨之云爾。不然，則何以曰「冒天下之道，而百姓與能」乎？</p><p>考象傳凡言「位當」、「不當」者，獨三、四、五三爻爾，初、二皆無之。蓋所謂「位」者，雖以爻位言，然實藉以明分位之義。初居卦下，上處卦外，無位者也。二雖有位，而未高者也。惟五居尊，而三、四皆當高位，故言「位當」、「不當」者，獨此三爻詳焉。凡言「位當」、「位正當」者，皆謂「德」與「位稱」也。不然，則謂時位有所適當，而必善所以處之也。凡言「位不當」、「未當」者，皆謂德不稱「位」也。不然，則謂時位有所未當，而必善所以處之也。大傳曰：「列貴賤者存乎位。」則知爻位有六，而貴者惟此三爻矣。以象傳之言「位當」、「位不當」者，施於此三爻，而不及其他，故知借爻位以明分位之義也。或曰：二雖未高，然亦有位焉，何以不言也？曰：據大傳「其柔危，其剛勝邪？」柔之為道，不利遠者，則三、五宜剛者也，四宜柔者也，二反宜剛者也。三、四、五以當為善，不當為不善，二則反以不當為善，故當不當之義，不得而施於此爻也。然其於三也，有言不當者矣，未有言當者也。於四也，有言當者矣，未有言正當者也。惟五言「正當」，其言不當者，獨「大壯」五而已，而又反以不當為善。蓋三，危位也，以柔居之固不當，以剛居之亦未必當也，此其所以多兇也。四近位也，以剛居之固不當，以柔居之亦僅止於「當」而已，此其所以「多懼」也。五尊位也，以剛居之為正當，以柔居之有柔之善焉，雖不當猶當也，此其所以「多功」也。</p><p>何以謂之德也？有根於卦者焉，「健順」、「動止」、「明說」之類是也；有生於爻者焉，「剛柔」、「中正」之類是也。德無常善，適時為善。故「健順」、「動止」「明說」之德，失其節則悖矣；剛柔之道，逆其施則拂矣。屯，宜用動者也；蹇，宜用止者也；豐，宜用明者也；困，宜用說者也；需，宜用剛者也；訟，宜用柔者也；賁，宜用剛者也；噬嗑，宜用柔者也；家人，宜用剛者也；旅，宜用柔者也。推此類之，則所謂德之善者可見矣。惟中也，正也，則無不宜也，而中為尤善，何也？易之義莫重於貞，然亦有「貞兇」者矣，有「貞吝」、「貞厲」者矣。其事未必不是也，而逆其時而不知變，且以為正而固守焉，則兇危之道也。中則義之精而用之妙，凡所謂健順、動止、明說、剛柔之施，於是取裁焉。先儒所謂中則無不正者，此也。或曰：「易之卦爻，於貞蓋諄諄焉，其於中行，僅數四見而已，何也？」曰：「正理可識，而中體難明，非深於道者不能知，是故難以察察言也。存其義而沒其名，則聖教之精也。自乾、坤二卦，固皆利於貞矣。然所謂二用者，則中之極而貞之源也。其餘卦之諸爻，居得其正者多矣，而亦鮮以正許之者。惟二與五得其正者，固曰以中正也。或不得其正者，亦曰中以行正也。是則中道之大，而易教之至也。」「然則存其義而沒其名者，何也？」曰：「六十四卦三百八十四爻，所繫皆中也。」然必曰如是則得其正，則人皆知道義之是守矣。倘必曰如是乃得其中，則有誤於依違兩可、混同無辨者，而不自知其非也。故舜之智，必問察乎善而後執其中；顏子之賢，擇乎中庸而必得其善。正非中，則正之實未至；中非正，則中之名亦易差。聖人所以尊中之道而略其名，精求乎正之實而必廣其教者，此也。</p><p>自王輔嗣說易，多取應爻為義，歷代因之。考之夫子彖、象傳，言應者蓋有之，然亦觀爻之一義爾。若逐爻必以應言，恐非周公之意，亦非孔子所以釋經之旨也。以經傳之例觀之，上下兩體，陰陽相求，固其正矣。然彖傳有以眾爻應一爻者，亦有以一爻應眾爻者，乃不拘於兩體二爻之對比，小畜、同人、大有、豫之類，皆是也。有時義所宜，以陰應陰而吉，以陽應陽而吉者，又不拘於陰陽之偶，晉、小過之「王母祖妣」，睽、豐之「元夫夷主」之類皆是也。有以承乘之爻為重者，則雖有應爻而不取。如觀之「觀光」，蹇之「來碩」，姤之「包魚」，鼎之「金鉉」，而隨則有「失丈夫」之失，觀則有「𬮭觀」之醜，姤則有「無魚之兇」，此類皆是也。其餘但就其爻之時位、才德起義，而不繫於應者，不可勝數，而欲一一以應義傅會之，則鑿矣。況爻所謂應者，必隔二位而相應，例也，不隔則非應矣。今有相應而為某爻間隔之說，又有某爻起而爭應之說，豈非鑿之又鑿者乎？說經者因此而不通，所謂至今為梗者矣。經傳又無此意，亦奚重而不更也。凡應，惟二五之應最吉，蓋皆有中德，而又各居當時之位也。其次則初四間有取焉。三上取應義絕少，其善者又加少也。易之道，陰暗求於陽明，不以陽求陰也；上位求於下位，不以下求上也。故凡六五、九二之有取於應義，則無不吉者，為以陰求陽，德上而下交，則在上者有虛中之美，居下者有自重之實，「蒙」、「師」、「泰」、「大有」之類是也。如取應義者，在於九五、六二，則時義所當，亦有相助之善。然求陽者在於下位，則往往有戒辭焉，屯「比」、「同人」、「萃」之類是也。初與四亦然。如六四、初九取應義，是四求初也，則吉，屯「賁」、「頤」、「損」是也。如九四、初六取應義，是初求四也，則兇，「大過」、「解」、「姤」、「鼎」是也。然吉者在四，而在初者不可變，上雖下交，而下不可以失己也。兇者在初，而在四者與之兇。下既援上，則上未免為失人矣。三上或取應義，皆非吉者，若蒙、頤、睽、夬、豐、中孚之類。惟剝之三與陽應，損之三當益上，於時義有取焉，故二爻無兇辭爾。承乘者謂之比，凡比爻，惟上體所取最多。蓋四承五，則如人臣之得君；五承上，則如人主之尊賢。主於五，故其近之者，皆多所取也。然四之承五，惟六四、九五當之。五之承上，惟六五、上九當之。非然者，則亦無得君尊賢之義。惟隨之五、上稍變斯例，以時義剛來下柔故爾。其餘九五比上六者，皆為剛德之累。上六從九五者，則為從貴之宜，非尊賢者比也。下體三爻，所取比義至少。初與二，二與三，間有相從者，隨其時義，或吉或否。至三與四，則隔體無相比之情矣。亦有因時變例取者，隨三、萃三是也。</p><p>象也者，像也。故或其卦取於物象，而爻當之，則遂以其義之吉凶斷，而爻德猶其次也。如屯所以為屯者，以其雷在下而未起也，初為震主當之，故曰「盤桓」。又以其雲在上而未下也，五為坎主當之，故曰「屯膏」。需所以為需，以其雲上於天也，九五坎主當之，故為「飲食宴樂」也。履之六三，說而承乾，本卦之主，然因彖言「咥人」，而三適當兌口之缺，有受咥之象，故其傳曰「位不當也」，言其直口之位為不當也。頤之初九，本有剛德，能自守者也，以其與上共為頤象。而頤之為物，其動在下，故曰「朵頤」而得「兇」也。鹹、艮以人身取象，故鹹二雖中正，以直腓位而兇；艮四雖不中正，以直背位而無咎。歸妹之兇，以女少而自歸故也。初九適當娣象，則不嫌於少，且自歸矣。六五適當帝女之象，則亦不嫌於自歸矣，故皆得吉也。節取澤與水為通塞，九二適在澤中，則塞之至也，故雖有剛德而兇也。凡若此類，以爻德比應求之，多所不通，惟明於象像之理則得之。又有卦雖取其象，而爻義不應者，則有變例。如噬嗑「頤中有物」，則初上兩爻象頤噬人者也；九四一爻象物噬於人者也。然既以用獄為卦義，則用刑者有位之事，故又變其所取之象，以從爻位，四反為刑獄之主，初上反為受刑之人也。</p><p>有一卦六爻，專取一事一物為象，而或一爻別取者，則其義因以異矣。如需諸爻皆取沙泥郊穴之象，而五獨曰「需於酒食」，則以五為需之主，有需之德，而所需之安也。蠱諸爻皆象父母，而上獨曰「不事王侯」，則以上九居卦之上，無復承於父母之象，人未有不事父母者，故曰「不事王侯」也。鹹諸爻皆取身象，惟四不取者，四直心位，因之以論心之感應，而所該者廣也。大壯諸爻取羊者三，其曰「壯趾」，曰「藩決」，亦羊象也。惟二不取者，有中德而居下體，不任壯者也。蹇諸爻皆取往來為象，惟二五不言者，五尊位，二王臣之位，義不避難，無往來者也。艮諸爻亦取身象，惟上不取者，九三雖亦艮主，而直心位，然止未極也，至上而後止，極則盡止之道者也。若此之類，皆其權於義者精，故其取於象者審也。或曰：四近君之位，蹇不取四為王臣，而取二，何也？曰：四近也，二遠也。當蹇之時，為近臣者，與君同心，來連而已。若冒險阻而濟艱難，則遠臣之事也，故曰「同功而異位」。</p><p>六爻之辭多稱卦名以起其端，例也。然有稱有不稱者，則義亦異矣。如同人，六爻皆當言同人，然惟三四不言者，既有伏莽乘墉之象，則非同人也。豫，六爻皆當言豫，然惟二五不言者，既有介石之操，貞疾之警，則非豫也。隨，六爻皆當言「隨」，然初、二、五、上不言，而惟三、四言之，則以陽倡陰隨理之正也。初、二、五、上以剛隨柔，雖合時義，而非隨之正。三、四以柔隨剛，雖非時義，而得隨之正也。蠱之諸爻言「蠱」，而惟上不言，蓋蠱者事也，上不事王侯，則無事矣。然事之壞也，自人心始，上之志可則，則其事莫高而莫尚焉。噬嗑諸爻言「噬」，惟初上別取，初上噬於人者也，不可言噬也。離諸爻皆不言「離」，惟二三言「離」，諸爻皆直昏夜及昏明之際，惟二三直日中與日昃也。遁諸爻皆言「遁」，惟二不言，二應五，不可遁者也。明夷諸爻皆言「明夷」，惟上不言，諸爻皆明而「夷」者，上則夷人之明，而非明夷也。夬諸爻惟三五言「夬」，一近陰，一應陰，當夬之任者也。姤諸爻惟上言「姤」，去初最遠，言「遇」者，幸其不遇也。歸妹惟二上不言「歸妹」，一不歸，一無所歸也。豐惟初五不言「豐」，一則未至日中，一則有以處乎日中也。旅惟五爻不言「旅」，旅之最貴者，則非旅也。渙惟初爻不言「渙」，渙之初則猶未渙也。節惟初二不言「節」。過而後節，節之初則無所事節也。中孚惟五爻言「孚」，德既中正，而又化邦之主也。既、未濟兩卦惟未濟三爻言「未濟」，他爻之既、未濟，皆時之為也，惟未濟之三時可濟矣，而不濟，則才之為也，故特言未濟以別之也。餘卦餘爻如此類者，皆可以義理推。周易通論卷一。</p>',20)])])}const m=t(n,[["render",r]]);export{f as __pageData,m as default};
